{"path":"/workspace/src/store.js","content":"import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const LIMITS = { title: 200, author: 200, notes: 5000 };

export class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

export function isBookId(value) {
  return typeof value === 'string' && ID_PATTERN.test(value);
}

export function validateBookInput(input) {
  const title = oneLine(input?.title);
  const author = oneLine(input?.author);
  const notes = noteText(input?.notes);

  if (!title || !author) {
    throw new ValidationError('Title and author are required.');
  }
  if (title.length > LIMITS.title || author.length > LIMITS.author) {
    throw new ValidationError('Title and author must be 200 characters or fewer.');
  }
  if (notes.length > LIMITS.notes) {
    throw new ValidationError('Notes must be 5,000 characters or fewer.');
  }

  return { title, author, notes };
}

export function createStore(filePath) {
  let chain = Promise.resolve();

  function exclusive(task) {
    const run = chain.then(task, task);
    chain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  async function read() {
    let text;
    try {
      text = await readFile(filePath, 'utf8');
    } catch (error) {
      if (error?.code === 'ENOENT') return { books: [] };
      throw error;
    }

    if (text.trim() === '') return { books: [] };

    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      throw new Error(`Books file is not valid JSON: ${filePath}`);
    }
    if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.books)) {
      throw new Error(`Books file must contain a books array: ${filePath}`);
    }

    return {
      books: parsed.books.map((book, index) => normalizeBook(book, index)),
    };
  }

  async function write(data) {
    await mkdir(dirname(filePath), { recursive: true });
    const temporary = `${filePath}.${process.pid}.tmp`;
    try {
      await writeFile(temporary, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
      await rename(temporary, filePath);
    } catch (error) {
      await rm(temporary, { force: true });
      throw error;
    }
  }

  return {
    list() {
      return exclusive(async () => {
        const data = await read();
        return {
          reading: data.books
            .filter((book) => book.status === 'reading')
            .sort((a, b) => b.addedAt.localeCompare(a.addedAt)),
          finished: data.books
            .filter((book) => book.status === 'finished')
            .sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || '')),
        };
      });
    },

    get(id) {
      return exclusive(async () => {
        const data = await read();
        return data.books.find((book) => book.id === id) || null;
      });
    },

    add(input) {
      return exclusive(async () => {
        const fields = validateBookInput(input);
        const data = await read();
        const book = {
          id: uniqueId(data.books),
          title: fields.title,
          author: fields.author,
          notes: fields.notes,
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        data.books.push(book);
        await write(data);
        return book;
      });
    },

    finish(id) {
      return exclusive(async () => {
        if (!isBookId(id)) return null;
        const data = await read();
        const book = data.books.find((item) => item.id === id);
        if (!book) return null;
        if (book.status !== 'finished') {
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
          await write(data);
        }
        return book;
      });
    },
  };
}

function normalizeBook(book, index) {
  if (!book || typeof book !== 'object') {
    throw new Error(`Book at index ${index} is invalid`);
  }
  if (!isBookId(book.id)) {
    throw new Error(`Book at index ${index} has an invalid id`);
  }
  if (typeof book.title !== 'string' || typeof book.author !== 'string') {
    throw new Error(`Book at index ${index} is missing a title or author`);
  }
  if (book.status !== 'reading' && book.status !== 'finished') {
    throw new Error(`Book at index ${index} has an invalid status`);
  }

  return {
    id: book.id,
    title: book.title,
    author: book.author,
    notes: typeof book.notes === 'string' ? book.notes : '',
    status: book.status,
    addedAt: typeof book.addedAt === 'string' ? book.addedAt : new Date(0).toISOString(),
    finishedAt:
      book.status === 'finished' && typeof book.finishedAt === 'string' ? book.finishedAt : null,
  };
}

function uniqueId(books) {
  const used = new Set(books.map((book) => book.id));
  for (let attempt = 0; attempt < 5; attempt += 1) {
    const id = randomBytes(6).toString('hex');
    if (!used.has(id)) return id;
  }
  throw new Error('Could not allocate a book id');
}

function oneLine(value) {
  return String(value ?? '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function noteText(value) {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}
"}

{"path":"/workspace/src/styles.css","content":":root {
  color-scheme: light;
  --bg: #f3efe6;
  --paper: #fffdf8;
  --ink: #1e1a16;
  --muted: #6e655c;
  --line: #e3dacb;
  --green: #1d5c45;
  --green-soft: #e7f2ec;
  --danger-bg: #fdecec;
  --danger: #7a2424;
}

* { box-sizing: border-box; }

::selection { background: #cfe3d8; }

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1000px 320px at 8% -8%, #efe4cf 0%, transparent 55%),
    var(--bg);
  color: var(--ink);
  font: 16px/1.5 ui-sans-serif, "Segoe UI", sans-serif;
}

.wrap {
  width: min(920px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 2.5rem 0 4.5rem;
}

.site {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 0.7rem;
  margin-bottom: 1.6rem;
}

.brand {
  color: inherit;
  text-decoration: none;
  font-family: Georgia, "Iowan Old Style", Palatino, serif;
  font-size: 1.8rem;
  letter-spacing: -0.04em;
  line-height: 1;
}

.brand::before {
  content: "";
  display: inline-block;
  width: 0.55rem;
  height: 0.9rem;
  margin-right: 0.45rem;
  background: var(--green);
  vertical-align: -0.05rem;
}

.brand:hover { color: var(--green); }

h1, h2, h3 {
  font-family: Georgia, "Iowan Old Style", Palatino, serif;
  font-weight: 600;
  letter-spacing: -0.03em;
}

h1 { font-size: 2rem; margin: 0 0 0.3rem; }
h2 { font-size: 1.2rem; margin: 0; }
h3 { font-size: 1.15rem; margin: 0; }

.lede, .hint, .footnote, .empty, .author, .meta {
  color: var(--muted);
}

.lede { margin: 0 0 1.5rem; }
.footnote { margin: 1.5rem 0 0; font-size: 0.92rem; }
.hint { margin: 0.35rem 0 0.55rem; font-size: 0.92rem; }

.shelves {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.shelf h2 {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.75rem;
  padding-bottom: 0.45rem;
  border-bottom: 1px solid var(--line);
  margin-bottom: 0.85rem;
}

.count {
  font-family: ui-sans-serif, "Segoe UI", sans-serif;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--muted);
}

.empty { margin: 0.2rem 0 0; }

.book {
  background: var(--paper);
  border: 1px solid var(--line);
  border-left: 3px solid var(--green);
  border-radius: 8px;
  padding: 0.85rem 0.9rem 0.75rem;
  margin: 0 0 0.7rem;
}

.book.finished { border-left-color: #c4b8a8; }

.book a {
  color: inherit;
  text-decoration: none;
  display: block;
}

.book a:hover h3 {
  text-decoration: underline;
  text-underline-offset: 0.18em;
}

.author { margin: 0.15rem 0 0; }

.book form { margin: 0.7rem 0 0; }

.add, .panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1.05rem 1.1rem 1.15rem;
}

.add { margin-top: 2rem; }
.shelves + .add { margin-top: 2rem; }
.add + .shelves { margin-top: 1.5rem; }

.add h2, .panel h2 { margin-bottom: 0.85rem; }

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem 0.9rem;
}

.full { grid-column: 1 / -1; }

label span, .kicker {
  display: block;
  margin-bottom: 0.3rem;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted);
}

.kicker { margin-bottom: 0.1rem; }

input, textarea {
  width: 100%;
  font: inherit;
  color: inherit;
  background: #fff;
  border: 1px solid #ddd3c4;
  border-radius: 8px;
  padding: 0.6rem 0.7rem;
}

textarea { min-height: 6.5rem; resize: vertical; }

input:focus, textarea:focus, button:focus-visible, a:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 2px;
}

.actions { display: flex; justify-content: flex-end; }

button {
  font: 600 0.92rem/1 ui-sans-serif, "Segoe UI", sans-serif;
  color: #f7f3ec;
  background: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.58rem 0.9rem;
  cursor: pointer;
}

button:hover { background: var(--green); border-color: var(--green); }

button.quiet {
  color: var(--ink);
  background: transparent;
  border-color: #cfc4b4;
}

button.quiet:hover {
  color: var(--green);
  background: var(--green-soft);
  border-color: var(--green);
}

.error {
  margin: 0 0 0.85rem;
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  background: var(--danger-bg);
  color: var(--danger);
}

.back { margin: 0 0 1rem; font-size: 0.92rem; }
.back a { color: var(--muted); }

.detail { max-width: 40rem; }

.status {
  display: inline-block;
  margin: 0 0 0.75rem;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  background: var(--green-soft);
  color: var(--green);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.status.done {
  background: #f0ebe3;
  color: var(--muted);
}

.by {
  margin: 0.2rem 0 0.4rem;
  font-size: 1.15rem;
}

.meta { margin: 0 0 0.4rem; font-size: 0.92rem; }

.notes {
  margin: 0.35rem 0 1.2rem;
  white-space: pre-wrap;
  font-family: Georgia, "Iowan Old Style", Palatino, serif;
  font-size: 1.12rem;
  line-height: 1.65;
}

.share { margin-top: 1.6rem; }
.share input {
  font-family: ui-monospace, "Cascadia Mono", monospace;
  font-size: 0.92rem;
  user-select: all;
}

@media (max-width: 720px) {
  .wrap { padding-top: 1.4rem; }
  .shelves, .grid { grid-template-columns: 1fr; }
  h1 { font-size: 1.7rem; }
}
"}

{"path":"/workspace/src/render.js","content":"import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const CSS = readFileSync(join(dirname(fileURLToPath(import.meta.url)), 'styles.css'), 'utf8');

export function renderHome({ shelf, error = '', draft = {} }) {
  const shelves = renderShelves(shelf);
  const form = renderAddForm({ error, draft });
  const hasBooks = shelf.reading.length + shelf.finished.length > 0;

  return layout({
    title: 'Shelf',
    body: `<main>
      <h1>Your books</h1>
      <p class="lede">What you're reading now, and what you've finished.</p>
      ${hasBooks ? shelves + form : form + shelves}
      <p class="footnote">Saved in a JSON file on this computer. No account.</p>
    </main>`,
  });
}

export function renderBook({ book, shareUrl }) {
  const finished = book.status === 'finished';
  const status = finished ? 'Finished' : 'Currently reading';
  const when = finished && book.finishedAt
    ? `Finished ${formatDate(book.finishedAt)}`
    : `Added ${formatDate(book.addedAt)}`;
  const notes = book.notes ? escapeHtml(book.notes) : 'No notes yet.';
  const finish = finished
    ? ''
    : `<form method="post" action="/books/${book.id}/finish">
        <input type="hidden" name="next" value="/books/${book.id}">
        <button type="submit">Mark finished</button>
      </form>`;

  return layout({
    title: `${book.title} · Shelf`,
    description: `${book.title} by ${book.author}`,
    extraHead: `<meta property="og:title" content="${escapeHtml(book.title)}">
<meta property="og:description" content="${escapeHtml(book.author)}">
<meta property="og:type" content="article">
<meta property="og:url" content="${escapeHtml(shareUrl)}">
<link rel="canonical" href="${escapeHtml(shareUrl)}">`,
    body: `<main class="detail">
      <p class="back"><a href="/">All books</a></p>
      <p class="status${finished ? ' done' : ''}">${status}</p>
      <h1>${escapeHtml(book.title)}</h1>
      <p class="by"><span class="kicker">Author</span>${escapeHtml(book.author)}</p>
      <p class="meta"><time datetime="${escapeHtml(finished ? book.finishedAt : book.addedAt)}">${escapeHtml(when)}</time></p>
      <h2>Notes</h2>
      <div class="notes">${notes}</div>
      ${finish}
      <section class="share">
        <h2>Link to this book</h2>
        <p class="hint">Copy this address to send someone this book.</p>
        <input id="share-link" readonly value="${escapeHtml(shareUrl)}" aria-label="Link to this book">
      </section>
    </main>`,
  });
}

export function renderMessage({ title, message }) {
  return layout({
    title: `${title} · Shelf`,
    body: `<main class="detail">
      <h1>${escapeHtml(title)}</h1>
      <p>${escapeHtml(message)}</p>
      <p class="back"><a href="/">All books</a></p>
    </main>`,
  });
}

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function renderShelves(shelf) {
  return `<div class="shelves">
    <section class="shelf" id="reading" aria-labelledby="reading-heading">
      <h2 id="reading-heading">Currently reading <span class="count">${shelf.reading.length}</span></h2>
      ${shelf.reading.map((book) => bookCard(book)).join('') || '<p class="empty">No books in progress.</p>'}
    </section>
    <section class="shelf" id="finished" aria-labelledby="finished-heading">
      <h2 id="finished-heading">Finished <span class="count">${shelf.finished.length}</span></h2>
      ${shelf.finished.map((book) => bookCard(book)).join('') || '<p class="empty">No finished books yet.</p>'}
    </section>
  </div>`;
}

function bookCard(book) {
  const finish = book.status === 'reading'
    ? `<form method="post" action="/books/${book.id}/finish">
        <input type="hidden" name="next" value="/">
        <button class="quiet" type="submit">Mark finished</button>
      </form>`
    : '';

  return `<article class="book${book.status === 'finished' ? ' finished' : ''}">
    <a href="/books/${book.id}">
      <h3>${escapeHtml(book.title)}</h3>
      <p class="author">${escapeHtml(book.author)}</p>
    </a>
    ${finish}
  </article>`;
}

function renderAddForm({ error, draft }) {
  return `<section class="add" aria-labelledby="add-heading">
    <h2 id="add-heading">Add a book</h2>
    ${error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : ''}
    <form method="post" action="/books" autocomplete="off">
      <div class="grid">
        <label class="full" for="title"><span>Title</span>
          <input id="title" name="title" required maxlength="200" value="${escapeHtml(draft.title || '')}">
        </label>
        <label class="full" for="author"><span>Author</span>
          <input id="author" name="author" required maxlength="200" value="${escapeHtml(draft.author || '')}">
        </label>
        <label class="full" for="notes"><span>Notes</span>
          <textarea id="notes" name="notes" maxlength="5000">${escapeHtml(draft.notes || '')}</textarea>
        </label>
        <div class="actions full">
          <button type="submit">Add book</button>
        </div>
      </div>
    </form>
  </section>`;
}

function layout({ title, description = '', extraHead = '', body }) {
  const descriptionTag = description
    ? `<meta name="description" content="${escapeHtml(description)}">`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>${escapeHtml(title)}</title>
${descriptionTag}
${extraHead}
<style>
${CSS}
</style>
</head>
<body>
<div class="wrap">
<header class="site">
  <a class="brand" href="/">Shelf</a>
</header>
${body}
</div>
</body>
</html>`;
}

function formatDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  }).format(date);
}
"}

{"path":"/workspace/src/server.js","content":"import { createServer as createHttpServer } from 'node:http';
import { renderBook, renderHome, renderMessage } from './render.js';
import { isBookId, ValidationError } from './store.js';

const MAX_BODY = 128 * 1024;

export function createServer(store) {
  return createHttpServer((req, res) => {
    handle(req, res, store).catch((error) => {
      try {
        fail(res, error);
      } catch (writeError) {
        console.error(writeError);
        res.destroy();
      }
    });
  });
}

async function handle(req, res, store) {
  const url = new URL(req.url || '/', 'http://127.0.0.1');
  let pathname = url.pathname;
  if (pathname.length > 1 && pathname.endsWith('/')) pathname = pathname.slice(0, -1);

  if (pathname === '/favicon.ico') {
    res.writeHead(204, { 'cache-control': 'no-store' });
    res.end();
    return;
  }

  let parts;
  try {
    parts = pathname.split('/').filter(Boolean).map((part) => decodeURIComponent(part));
  } catch {
    send(res, 400, renderMessage({ title: 'Bad request', message: 'That address is not valid.' }));
    return;
  }

  if (parts.length === 0) {
    if (req.method !== 'GET') {
      methodNotAllowed(res);
      return;
    }
    send(res, 200, renderHome({ shelf: await store.list() }));
    return;
  }

  if (parts[0] !== 'books') {
    notFound(res);
    return;
  }

  if (parts.length === 1) {
    if (req.method === 'GET') {
      redirect(res, '/');
      return;
    }
    if (req.method !== 'POST') {
      methodNotAllowed(res);
      return;
    }
    await addBook(req, res, store);
    return;
  }

  const id = parts[1];
  const finishing = parts.length === 3 && parts[2] === 'finish';
  if (!isBookId(id) || parts.length > 3 || (parts.length === 3 && !finishing)) {
    notFound(res);
    return;
  }

  if (parts.length === 2) {
    if (req.method !== 'GET') {
      methodNotAllowed(res);
      return;
    }
    const book = await store.get(id);
    if (!book) {
      send(res, 404, renderMessage({ title: 'Book not found', message: 'That book is not on the shelf.' }));
      return;
    }
    send(res, 200, renderBook({ book, shareUrl: shareUrl(req, book.id) }));
    return;
  }

  if (req.method !== 'POST') {
    methodNotAllowed(res);
    return;
  }

  const form = await readForm(req);
  const book = await store.finish(id);
  if (!book) {
    send(res, 404, renderMessage({ title: 'Book not found', message: 'That book is not on the shelf.' }));
    return;
  }
  redirect(res, safeNext(form.next, book.id));
}

async function addBook(req, res, store) {
  const form = await readForm(req);
  try {
    await store.add(form);
  } catch (error) {
    if (!(error instanceof ValidationError)) throw error;
    send(res, 400, renderHome({
      shelf: await store.list(),
      error: error.message,
      draft: form,
    }));
    return;
  }
  redirect(res, '/');
}

function shareUrl(req, id) {
  return `${originOf(req)}/books/${id}`;
}

function originOf(req) {
  const forwarded = headerValue(req.headers['x-forwarded-proto']);
  const proto = forwarded && /^https?$/.test(forwarded) ? forwarded : 'http';
  const host = headerValue(req.headers['x-forwarded-host']) || headerValue(req.headers.host) || '127.0.0.1';
  if (!/^[A-Za-z0-9.:-]+$/.test(host)) return '';
  return `${proto}://${host}`;
}

function headerValue(value) {
  const raw = Array.isArray(value) ? value[0] : value;
  if (typeof raw !== 'string') return '';
  return raw.split(',')[0].trim();
}

function safeNext(next, id) {
  if (next === '/') return '/';
  if (next === `/books/${id}`) return next;
  return '/';
}

function readForm(req) {
  return readBody(req).then((raw) => {
    const params = new URLSearchParams(raw);
    return {
      title: params.get('title') ?? '',
      author: params.get('author') ?? '',
      notes: params.get('notes') ?? '',
      next: params.get('next') ?? '',
    };
  });
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    let settled = false;

    function fail(error) {
      if (settled) return;
      settled = true;
      reject(error);
    }

    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        const error = new Error('Payload too large');
        error.statusCode = 413;
        fail(error);
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (settled) return;
      settled = true;
      resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', fail);
  });
}

function redirect(res, location) {
  res.writeHead(303, {
    location,
    'cache-control': 'no-store',
  });
  res.end();
}

function notFound(res) {
  send(res, 404, renderMessage({ title: 'Page not found', message: 'That page is not on the shelf.' }));
}

function methodNotAllowed(res) {
  send(res, 405, renderMessage({ title: 'Method not allowed', message: 'That action is not available.' }));
}

function fail(res, error) {
  const status = Number.isInteger(error?.statusCode) ? error.statusCode : 500;
  if (status >= 500) console.error(error);
  if (res.headersSent) {
    res.destroy();
    return;
  }
  const message = status === 413
    ? 'That form was too large to save.'
    : status === 400
      ? 'That request could not be read.'
      : 'The shelf could not be loaded.';
  const title = status === 500 ? 'Something went wrong' : 'Request not saved';
  send(res, status, renderMessage({ title, message }));
}

function send(res, status, html) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
    'referrer-policy': 'no-referrer',
    'content-security-policy': "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
    'x-frame-options': 'DENY',
  });
  res.end(html);
}
"}

