  await Promise.all(directories.splice(0).map((dir) => rm(dir, { recursive: true, force: true })));
});

async function tempFile(name = 'books.json') {
  const dir = await mkdtemp(join(tmpdir(), 'shelf-'));
  directories.push(dir);
  return join(dir, name);
}

describe('book store', () => {
  it('adds a reading book and reads it back from a new store', async () => {
    const file = await tempFile();
    const store = createStore(file);

    const book = await store.add({
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'Ambiguous utopia.\nSecond line.',
    });

    expect(book.status).toBe('reading');
    expect(book.finishedAt).toBeNull();

    const shelf = await store.list();
    expect(shelf.reading.map((item) => item.title)).toEqual(['The Dispossessed']);
    expect(shelf.finished).toEqual([]);

    const restarted = createStore(file);
    const saved = await restarted.get(book.id);
    expect(saved).toMatchObject({
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'Ambiguous utopia.\nSecond line.',
      status: 'reading',
    });

    const raw = JSON.parse(await readFile(file, 'utf8'));
    expect(raw.books).toHaveLength(1);
    expect(raw.books[0].id).toBe(book.id);
  });

  it('moves a finished book out of the reading list', async () => {
    const file = await tempFile();
    const store = createStore(file);
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: '' });

    const finished = await store.finish(book.id);
    expect(finished.status).toBe('finished');
    expect(finished.finishedAt).toEqual(expect.any(String));

    const again = await store.finish(book.id);
    expect(again.finishedAt).toBe(finished.finishedAt);

    const shelf = await createStore(file).list();
    expect(shelf.reading).toEqual([]);
    expect(shelf.finished.map((item) => item.id)).toEqual([book.id]);
  });

  it('rejects a book without a title or author', async () => {
    const store = createStore(await tempFile());
    await expect(store.add({ title: '  ', author: 'Someone', notes: '' })).rejects.toBeInstanceOf(ValidationError);
    await expect(store.list()).resolves.toEqual({ reading: [], finished: [] });
  });

  it('returns null for an unknown book and does not create a file', async () => {
    const file = await tempFile('missing/books.json');
    const store = createStore(file);
    await expect(store.get('missing-book')).resolves.toBeNull();
    await expect(store.finish('missing-book')).resolves.toBeNull();
