{"path":"/workspace/test/server.test.js","content":"import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { createServer } from '../src/server.js';
import { createStore } from '../src/store.js';

const cleanups = [];

afterEach(async () => {
  while (cleanups.length) await cleanups.pop()();
});

async function boot(file = '') {
  const dir = await mkdtemp(join(tmpdir(), 'shelf-'));
  const booksFile = file || join(dir, 'books.json');
  const server = createServer(createStore(booksFile));
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address();
  cleanups.push(async () => {
    server.closeAllConnections();
    await new Promise((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
    await rm(dir, { recursive: true, force: true });
  });
  return { base: `http://127.0.0.1:${port}`, file: booksFile, dir };
}

function post(url, fields) {
  return fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

function section(html, id) {
  const start = html.indexOf(`id="${id}"`);
  const endMarker = id === 'reading' ? 'id="finished"' : 'class="add"';
  const end = html.indexOf(endMarker, start + 1);
  return html.slice(start, end === -1 ? undefined : end);
}

describe('shelf server', () => {
  it('shows the shelf, adds a book, finishes it, and serves a direct link', async () => {
    const { base, file } = await boot();
    const home = await (await fetch(base)).text();
    expect(home).toContain('Currently reading');
    expect(home).toContain('Finished');
    expect(home).toContain('Add a book');
    expect(home).toContain('No books in progress.');

    const added = await post(`${base}/books`, {
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'Ambiguous utopia.',
    });
    expect(added.status).toBe(303);
    expect(added.headers.get('location')).toBe('/');

    const afterAdd = await (await fetch(base)).text();
    expect(section(afterAdd, 'reading')).toContain('The Dispossessed');
    expect(section(afterAdd, 'reading')).toContain('Ursula K. Le Guin');
    expect(section(afterAdd, 'reading')).toContain('Mark finished');
    expect(section(afterAdd, 'finished')).not.toContain('The Dispossessed');

    const id = section(afterAdd, 'reading').match(/\/books\/([A-Za-z0-9_-]+)/)[1];
    const detail = await (await fetch(`${base}/books/${id}`)).text();
    expect(detail).toContain('The Dispossessed');
    expect(detail).toContain('Ursula K. Le Guin');
    expect(detail).toContain('Ambiguous utopia.');
    expect(detail).toContain('Notes');
    expect(detail).toContain(`${base}/books/${id}`);

    const finished = await post(`${base}/books/${id}/finish`, { next: '/' });
    expect(finished.status).toBe(303);
    expect(finished.headers.get('location')).toBe('/');

    const afterFinish = await (await fetch(base)).text();
    expect(section(afterFinish, 'reading')).not.toContain('The Dispossessed');
    expect(section(afterFinish, 'finished')).toContain('The Dispossessed');
    expect(section(afterFinish, 'finished')).not.toContain('Mark finished');

    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved.books[0]).toMatchObject({ id, status: 'finished', title: 'The Dispossessed' });
  });

  it('keeps the same book page after a restart', async () => {
    const dir = await mkdtemp(join(tmpdir(), 'shelf-restart-'));
    const file = join(dir, 'books.json');
    const first = await boot(file);
    await post(`${first.base}/books`, {
      title: 'Kindred',
      author: 'Octavia E. Butler',
      notes: 'Time and blood.',
    });
    const id = JSON.parse(await readFile(file, 'utf8')).books[0].id;

    const second = await boot(file);
    const page = await (await fetch(`${second.base}/books/${id}`)).text();
    expect(page).toContain('Kindred');
    expect(page).toContain('Octavia E. Butler');
    expect(page).toContain('Time and blood.');
    expect(page).toContain(`/books/${id}`);
    await rm(dir, { recursive: true, force: true });
  });

  it('keeps the draft and escapes it when the form is incomplete', async () => {
    const { base } = await boot();
    const response = await post(`${base}/books`, {
      title: '<script>alert(1)</script>',
      author: '',
      notes: 'hello',
    });
    expect(response.status).toBe(400);
    const html = await response.text();
    expect(html).toContain('Title and author are required.');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).not.toContain('<script>alert(1)</script>');
  });

  it('returns not found for an unknown book', async () => {
    const { base } = await boot();
    const response = await fetch(`${base}/books/not-a-book`);
    expect(response.status).toBe(404);
    expect(await response.text()).toContain('Book not found');
  });
});
"}

